window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_11", [
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. राष्ट्रकूट वंश : दंतिदुर्ग (752 ई.)\n2. कुषाण वंश : सिंहविष्णु (छठी शती ई.)\n3. कांची के पल्लव : गोपाल (लगभग 750 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया।) युग्म 2 गलत (सही: कुषाण वंश — कुजुल कडफिसेस)। युग्म 3 गलत (सही: कांची के पल्लव — सिंहविष्णु (छठी शती ई.))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्राचीन राजवंश एवं संस्थापक के अंतर्गत 'राष्ट्रकूट वंश' का ऐतिहासिक संबंध 'गोपाल (लगभग 750 ई.)' से था।\nकथन-2: प्राचीन स्मारक एवं निर्माता के अंतर्गत 'कांची का कैलाशनाथ मंदिर' का ऐतिहासिक संबंध 'उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'राष्ट्रकूट वंश' का सही संबंध 'दंतिदुर्ग (752 ई.)' से था — दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया। (2) 'कांची का कैलाशनाथ मंदिर' का सही संबंध 'पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'' से था — राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. हर्यक वंश : सिंहविष्णु (छठी शती ई.)\n2. कांची के पल्लव : पुलकेशिन प्रथम (जयसिंह के वंशज)\n3. बंगाल का सेन वंश : सामंतसेन / विजयसेन\n4. बादामी के चालुक्य : श्रीगुप्त (तीसरी शती ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया। (अन्य सही युग्म: हर्यक वंश→बिम्बिसार (राजधानी: राजगृह), कांची के पल्लव→सिंहविष्णु (छठी शती ई.), बादामी के चालुक्य→पुलकेशिन प्रथम (जयसिंह के वंशज))।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन स्मारक एवं निर्माता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भीतरगाँव मंदिर (कानपुर) : राष्ट्रकूट नरेश कृष्ण प्रथम\n2. एलिफेंटा त्रिमूर्ति (घारापुरी) : कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)\n3. एलोरा का कैलाश मंदिर : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\n4. कांची का कैलाशनाथ मंदिर : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं। (अन्य सही युग्म: भीतरगाँव मंदिर (कानपुर)→पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर, एलोरा का कैलाश मंदिर→राष्ट्रकूट नरेश कृष्ण प्रथम, कांची का कैलाशनाथ मंदिर→पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह')।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. कुषाण वंश : दंतिदुर्ग (752 ई.)\n2. राष्ट्रकूट वंश : श्रीगुप्त (तीसरी शती ई.)\n3. गुप्त वंश : बिम्बिसार (राजधानी: राजगृह)\n4. कांची के पल्लव : सिंहविष्णु (छठी शती ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी। (अन्य सही युग्म: कुषाण वंश→कुजुल कडफिसेस, राष्ट्रकूट वंश→दंतिदुर्ग (752 ई.), गुप्त वंश→श्रीगुप्त (तीसरी शती ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन स्मारक एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कांची का कैलाशनाथ मंदिर : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\n2. भीतरगाँव मंदिर (कानपुर) : पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर\n3. एलोरा का कैलाश मंदिर : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए।) युग्म 2 सही (गुप्तकालीन भीतरगाँव मंदिर पूरी तरह पक्की ईंटों से बना व अर्धवृत्ताकार मेहराबदार छत रखता है।) युग्म 3 गलत (सही: एलोरा का कैलाश मंदिर — राष्ट्रकूट नरेश कृष्ण प्रथम)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख   B. शिशुनाग एवं नंद वंश (महापद्मनंद व घनानंद)\nC. अशोक के बाद मौर्य वंश का पतन एवं कारण   D. ऐहोल अभिलेख (634 ई.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अभिलेख (634 ई.)","शिशुनाग एवं नंद वंश (महापद्मनंद व घनानंद)","कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख","अशोक के बाद मौर्य वंश का पतन एवं कारण"],"correct":0,"explanation":"शिशुनाग एवं नंद वंश (महापद्मनंद व घनानंद) (344 ई.पू.), अशोक के बाद मौर्य वंश का पतन एवं कारण (185 ई.पू.), कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख (प्रथम शती ई.पू.), ऐहोल अभिलेख (634 ई.) (634 ई.)। अतः सबसे अंत में ऐहोल अभिलेख (634 ई.)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. चंद्रगुप्त द्वितीय 'विक्रमादित्य' एवं महरौली लौह स्तंभ   B. कांची का कैलाशनाथ मंदिर\nC. राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष   D. शक शासक रुद्रदामन I एवं जूनागढ़ (गिरनार) अभिलेख\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["चंद्रगुप्त द्वितीय 'विक्रमादित्य' एवं महरौली लौह स्तंभ","कांची का कैलाशनाथ मंदिर","वंश एवं","शक शासक रुद्रदामन I एवं जूनागढ़ (गिरनार) अभिलेख"],"correct":2,"explanation":"शक शासक रुद्रदामन I एवं जूनागढ़ (गिरनार) अभिलेख (150 ई.), चंद्रगुप्त द्वितीय 'विक्रमादित्य' एवं महरौली लौह स्तंभ (375-415 ई.), कांची का कैलाशनाथ मंदिर (700-728 ई.), राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष (752 ई.)। अतः सबसे अंत में राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्राचीन राजवंश एवं संस्थापक के अंतर्गत 'पाल राजवंश' का ऐतिहासिक संबंध 'सामंतसेन / विजयसेन' से था।\nकथन-2: चंद्रगुप्त मौर्य ने सेल्यूकस को 500 हाथी उपहार दिए, सेल्यूकस की पुत्री हेलेना (कार्नेलिया) से विवाह किया तथा दरबार में राजदूत मेगस्थनीज आया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('पाल राजवंश' का सही संबंध 'गोपाल (लगभग 750 ई.)' से था — गोपाल ने बंगाल में अराजकता समाप्त कर 750 ई. में पाल राजवंश की नींव रखी।)। कथन-2 सत्य है (चंद्रगुप्त मौर्य ने सेल्यूकस को 500 हाथी उपहार दिए, सेल्यूकस की पुत्री हेलेना (कार्नेलिया) से विवाह किया तथा दरबार में राजदूत मेगस्थनीज आया।)।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. कांची के पल्लव : कुजुल कडफिसेस\n2. कुषाण वंश : श्रीगुप्त (तीसरी शती ई.)\n3. बादामी के चालुक्य : पुलकेशिन प्रथम (जयसिंह के वंशज)\n4. गुप्त वंश : दंतिदुर्ग (752 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: पुलकेशिन प्रथम ने छठी सदी (लगभग 543 ई.) में वातापी को राजधानी बनाकर चालुक्य सत्ता स्थापित की। (अन्य सही युग्म: कांची के पल्लव→सिंहविष्णु (छठी शती ई.), कुषाण वंश→कुजुल कडफिसेस, गुप्त वंश→श्रीगुप्त (तीसरी शती ई.))।"},
  {"q":"राष्ट्रकूट राजवंश (मान्याखेट) का संस्थापक कौन था?","options":["दंतिदुर्ग (752 ई.)","कुजुल कडफिसेस","बिम्बिसार (राजधानी: राजगृह)","सिमुक (राजधानी: प्रतिष्ठान/पैठण)"],"correct":0,"explanation":"दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया। दंतिदुर्ग ने उज्जैनी में हिरण्यगर्भ महादान यज्ञ संपन्न कराया था।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. हर्यक वंश: बिम्बिसार एवं अजातशत्रु   B. पाल राजवंश\nC. मल्ल महाजनपद   D. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["हर्यक वंश: बिम्बिसार एवं अजातशत्रु","नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)","मल्ल महाजनपद","पाल"],"correct":3,"explanation":"मल्ल महाजनपद (600 ई.पू.), हर्यक वंश: बिम्बिसार एवं अजातशत्रु (544 ई.पू.), नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) (618 ई.), पाल राजवंश (750 ई.)। अतः सबसे अंत में पाल राजवंश।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया।\nकथन-2: ऋग्वेद में आधुनिक झेलम नदी को 'वितस्ता' कहा गया है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया। (2) ऋग्वेद में आधुनिक झेलम नदी को 'वितस्ता' कहा गया है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: पाल वंश के संस्थापक गोपाल को अराजकता (मात्स्यन्याय) समाप्त करने के लिए जनता/प्रमुख नागरिकों द्वारा राजा चुना गया था (खालिमपुर अभिलेख)।\nकथन-2: गुप्तकालीन नाटककार विशाखदत्त ने 'मुद्राराक्षस' तथा 'देवीचंद्रगुप्तम्' की रचना की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) पाल वंश के संस्थापक गोपाल को अराजकता (मात्स्यन्याय) समाप्त करने के लिए जनता/प्रमुख नागरिकों द्वारा राजा चुना गया था (खालिमपुर अभिलेख)। (2) गुप्तकालीन नाटककार विशाखदत्त ने 'मुद्राराक्षस' तथा 'देवीचंद्रगुप्तम्' की रचना की।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्राचीन स्मारक एवं निर्माता के अंतर्गत 'कांची का कैलाशनाथ मंदिर' का ऐतिहासिक संबंध 'उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)' से था।\nकथन-2: पाँचवें वृहद शिलालेख में अशोक ने सर्वप्रथम धम्म महामात्रों की नियुक्ति का उल्लेख किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('कांची का कैलाशनाथ मंदिर' का सही संबंध 'पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'' से था — राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए।)। कथन-2 सत्य है (पाँचवें वृहद शिलालेख में अशोक ने सर्वप्रथम धम्म महामात्रों की नियुक्ति का उल्लेख किया।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. कुषाण वंश : कुजुल कडफिसेस\n2. गुप्त वंश : श्रीगुप्त (तीसरी शती ई.)\n3. पाल राजवंश : पुलकेशिन प्रथम (जयसिंह के वंशज)\n4. राष्ट्रकूट वंश : दंतिदुर्ग (752 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'पाल राजवंश' का सही संबंध 'गोपाल (लगभग 750 ई.)' से है (न कि 'पुलकेशिन प्रथम (जयसिंह के वंशज)' से)। गोपाल ने बंगाल में अराजकता समाप्त कर 750 ई. में पाल राजवंश की नींव रखी।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन स्मारक एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कांची का कैलाशनाथ मंदिर : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\n2. एलिफेंटा त्रिमूर्ति (घारापुरी) : कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)\n3. एलोरा का कैलाश मंदिर : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए।) युग्म 2 सही (एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं।) युग्म 3 गलत (सही: एलोरा का कैलाश मंदिर — राष्ट्रकूट नरेश कृष्ण प्रथम)।"},
  {"q":"वातापी (बादामी) के चालुक्य वंश की स्थापना किसने की थी?","options":["पुलकेशिन प्रथम (जयसिंह के वंशज)","कुजुल कडफिसेस","बिम्बिसार (राजधानी: राजगृह)","सिमुक (राजधानी: प्रतिष्ठान/पैठण)"],"correct":0,"explanation":"पुलकेशिन प्रथम ने छठी सदी (लगभग 543 ई.) में वातापी को राजधानी बनाकर चालुक्य सत्ता स्थापित की। इस वंश का सबसे प्रतापी सम्राट पुलकेशिन द्वितीय (हर्ष का समकालीन) हुआ।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्राचीन राजवंश एवं संस्थापक के अंतर्गत 'राष्ट्रकूट वंश' का ऐतिहासिक संबंध 'गोपाल (लगभग 750 ई.)' से था।\nकथन-2: जैन तीर्थंकर प्रतीक के अंतर्गत 'सल्लेखना / संथारा' का ऐतिहासिक संबंध 'प्रतीक चिह्न: वृषभ (बैल)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'राष्ट्रकूट वंश' का सही संबंध 'दंतिदुर्ग (752 ई.)' से था — दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया। (2) 'सल्लेखना / संथारा' का सही संबंध 'उपवास द्वारा स्वेच्छा से देहत्याग की जैन विधि' से था — चंद्रगुप्त मौर्य ने भद्रबाहु के साथ श्रवणबेलगोला में सल्लेखना द्वारा प्राण त्यागे।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कुषाण वंश   B. सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ\nC. बंगाल का सेन वंश   D. तेरहवाँ वृहद शिलालेख\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सेन वंश","सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ","कुषाण वंश","तेरहवाँ वृहद शिलालेख"],"correct":0,"explanation":"सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ (600 ई.पू.), तेरहवाँ वृहद शिलालेख (261 ई.पू.), कुषाण वंश (प्रथम शती ई.), बंगाल का सेन वंश (1095 ई.)। अतः सबसे अंत में बंगाल का सेन वंश।"},
  {"q":"नर्मदा नदी के तट पर 618 ई. के लगभग चालुक्य सम्राट पुलकेशिन द्वितीय ने किसे पराजित किया?","options":["सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की","राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया","राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","नरेश ने हर्षवर्धन को हराया"],"correct":3,"explanation":"नर्मदा नदी तट पर बादामी चालुक्य शासक पुलकेशिन द्वितीय ने कन्नौज सम्राट हर्षवर्धन के दक्षिण अभियान को रोका। रविकीर्ति द्वारा रचित 'ऐहोल प्रशस्ति' में इस विजय का विस्तृत उल्लेख है।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\n2. पानीपत का तृतीय युद्ध (1761 ई.) : अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया\n3. हाइडेस्पीज का युद्ध (326 ई.पू.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (नर्मदा नदी तट पर बादामी चालुक्य शासक पुलकेशिन द्वितीय ने कन्नौज सम्राट हर्षवर्धन के दक्षिण अभियान को रोका।) युग्म 2 सही (पानीपत के तृतीय युद्ध में अफगान शासक अहमद शाह अब्दाली ने मराठों को निर्णायक रूप से हराया।) युग्म 3 गलत (सही: हाइडेस्पीज का युद्ध (326 ई.पू.) — सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: गोपाल ने बंगाल में अराजकता समाप्त कर 750 ई. में पाल राजवंश की नींव रखी।\nकथन-2: जैन तीर्थंकर एवं परंपरा के अंतर्गत 'पार्श्वनाथ (23वें तीर्थंकर)' का ऐतिहासिक संबंध 'श्वेतांबर परंपरा में स्त्री तीर्थंकर मान्यता' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (गोपाल ने बंगाल में अराजकता समाप्त कर 750 ई. में पाल राजवंश की नींव रखी।)। कथन-2 गलत है — 'पार्श्वनाथ (23वें तीर्थंकर)' का सही संबंध 'वाराणसी (काशी) जन्म — प्रतीक: सर्प फण' से था — काशी के राजा अश्वसेन के पुत्र पार्श्वनाथ ने झारखंड के सम्मेद शिखर (पार्श्वनाथ पहाड़ी) पर निर्वाण पाया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन स्मारक एवं निर्माता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भीतरगाँव मंदिर (कानपुर) : पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर\n2. एलोरा का कैलाश मंदिर : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\n3. एलिफेंटा त्रिमूर्ति (घारापुरी) : कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)\n4. दशावतार मंदिर (देवगढ़) : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'एलोरा का कैलाश मंदिर' का सही संबंध 'राष्ट्रकूट नरेश कृष्ण प्रथम' से है (न कि 'पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'' से)। कृष्ण प्रथम ने ऊपर से नीचे की ओर एक ही बेसाल्ट पहाड़ी काटकर कैलाश मंदिर बनवाया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कुमारगुप्त I, स्कंदगुप्त एवं हूण आक्रमण   B. सम्राट अशोक एवं कलिंग युद्ध (13वाँ वृहद शिलालेख)\nC. गौड़ नरेश शशांक, कामरूप व पाल-सेन राजवंश   D. गुप्त वंश\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["कुमारगुप्त I, स्कंदगुप्त एवं हूण आक्रमण","गुप्त वंश","सम्राट अशोक एवं कलिंग युद्ध (13वाँ वृहद शिलालेख)","व पाल-सेन"],"correct":3,"explanation":"सम्राट अशोक एवं कलिंग युद्ध (13वाँ वृहद शिलालेख) (261 ई.पू.), गुप्त वंश (275 ई.), कुमारगुप्त I, स्कंदगुप्त एवं हूण आक्रमण (510 ई.), गौड़ नरेश शशांक, कामरूप व पाल-सेन राजवंश (750 ई.)। अतः सबसे अंत में गौड़ नरेश शशांक, कामरूप व पाल-सेन राजवंश।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: राष्ट्रकूट नरेश ध्रुव (धारावर्ष) दक्षिण से उत्तर भारत की राजनीति में हस्तक्षेप कर कन्नौज त्रिकोणीय संघर्ष जीतने वाला पहला दक्कनी शासक था।\nकथन-2: गुप्त काल में महिलाओं की सामाजिक स्थिति में भारी सुधार हुआ तथा स्त्रियों को वेदों का स्वतंत्र पाठ करने व संपत्ति का पूर्ण स्वामित्व स्वतः मिल गया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (राष्ट्रकूट नरेश ध्रुव (धारावर्ष) दक्षिण से उत्तर भारत की राजनीति में हस्तक्षेप कर कन्नौज त्रिकोणीय संघर्ष जीतने वाला पहला दक्कनी शासक था।)। कथन-2 गलत है — गुप्त काल में स्त्रियों की दशा में गिरावट आई (विवाह की आयु घटी, सती प्रथा का साक्ष्य), हालांकि याज्ञवल्क्य आदि ने 'स्त्रीधन' पर अधिकार स्वीकार किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. बंगाल का सेन वंश : सामंतसेन / विजयसेन\n2. पाल राजवंश : गोपाल (लगभग 750 ई.)\n3. कांची के पल्लव : बिम्बिसार (राजधानी: राजगृह)\n4. गुप्त वंश : श्रीगुप्त (तीसरी शती ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'कांची के पल्लव' का सही संबंध 'सिंहविष्णु (छठी शती ई.)' से है (न कि 'बिम्बिसार (राजधानी: राजगृह)' से)। सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: चीनी यात्री ह्वेनसांग ने हर्ष के काल में भारत भ्रमण किया और बताया कि समाज में अस्पृश्यता विद्यमान थी, सूती/कौशेय वस्त्र प्रमुख थे और राजकोष 4 भागों में बँटता था।\nकथन-2: चंद्रगुप्त प्रथम ने 319-20 ई. में गुप्त संवत चलाया व 'महाराजाधिराज' उपाधि ली, जबकि समुद्रगुप्त ने उत्तर भारत में प्रत्यक्ष और दक्षिण में करद नीति अपनाई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) चीनी यात्री ह्वेनसांग ने हर्ष के काल में भारत भ्रमण किया और बताया कि समाज में अस्पृश्यता विद्यमान थी, सूती/कौशेय वस्त्र प्रमुख थे और राजकोष 4 भागों में बँटता था। (2) चंद्रगुप्त प्रथम ने 319-20 ई. में गुप्त संवत चलाया व 'महाराजाधिराज' उपाधि ली, जबकि समुद्रगुप्त ने उत्तर भारत में प्रत्यक्ष और दक्षिण में करद नीति अपनाई।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक युद्ध एवं परिणाम] सूची-I को सूची-II से सुमेलित कीजिए:\nA. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)   |   1. नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया\nB. करनाल का युद्ध (1739 ई.)   |   2. सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\nC. दाशराज्ञ युद्ध (परुष्णी नदी)   |   3. चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\nD. हाइडेस्पीज का युद्ध (326 ई.पू.)   |   4. राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","options":["A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) (चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया), करनाल का युद्ध (1739 ई.) (नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया), दाशराज्ञ युद्ध (परुष्णी नदी) (राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया), हाइडेस्पीज का युद्ध (326 ई.पू.) (सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन स्मारक एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. एलिफेंटा त्रिमूर्ति (घारापुरी) : कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)\n2. एलोरा का कैलाश मंदिर : राष्ट्रकूट नरेश कृष्ण प्रथम\n3. दशावतार मंदिर (देवगढ़) : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं।) युग्म 2 सही (कृष्ण प्रथम ने ऊपर से नीचे की ओर एक ही बेसाल्ट पहाड़ी काटकर कैलाश मंदिर बनवाया।) युग्म 3 सही (देवगढ़ का दशावतार मंदिर विष्णु के अनंतशायी व गजेंद्रमोक्ष शिल्पों के लिए प्रसिद्ध है।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बंगाल का सेन वंश   B. कांची का कैलाशनाथ मंदिर\nC. अंग महाजनपद   D. हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["सेन वंश","अंग महाजनपद","हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश)","कांची का कैलाशनाथ मंदिर"],"correct":0,"explanation":"अंग महाजनपद (600 ई.पू.), हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश) (606-647 ई.), कांची का कैलाशनाथ मंदिर (700-728 ई.), बंगाल का सेन वंश (1095 ई.)। अतः सबसे अंत में बंगाल का सेन वंश।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कांची के पल्लव : सिंहविष्णु (छठी शती ई.)\n2. बंगाल का सेन वंश : सामंतसेन / विजयसेन\n3. सातवाहन वंश : सिमुक (राजधानी: प्रतिष्ठान/पैठण)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी।) युग्म 2 सही (कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया।) युग्म 3 सही (सिमुक ने कण्व वंश के अंतिम शासक सुशर्मा को मारकर सातवाहन वंश की स्थापना की।)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बादामी के चालुक्य : पुलकेशिन प्रथम (जयसिंह के वंशज)\n2. हर्यक वंश : दंतिदुर्ग (752 ई.)\n3. राष्ट्रकूट वंश : सामंतसेन / विजयसेन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (पुलकेशिन प्रथम ने छठी सदी (लगभग 543 ई.) में वातापी को राजधानी बनाकर चालुक्य सत्ता स्थापित की।) युग्म 2 गलत (सही: हर्यक वंश — बिम्बिसार (राजधानी: राजगृह))। युग्म 3 गलत (सही: राष्ट्रकूट वंश — दंतिदुर्ग (752 ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कांची के पल्लव : सिंहविष्णु (छठी शती ई.)\n2. बंगाल का सेन वंश : सामंतसेन / विजयसेन\n3. बादामी के चालुक्य : बिम्बिसार (राजधानी: राजगृह)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी।) युग्म 2 सही (कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया।) युग्म 3 गलत (सही: बादामी के चालुक्य — पुलकेशिन प्रथम (जयसिंह के वंशज))।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कुरु महाजनपद   B. कांची का कैलाशनाथ मंदिर\nC. पाल राजवंश   D. चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["कुरु महाजनपद","कांची का कैलाशनाथ मंदिर","चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)","पाल"],"correct":3,"explanation":"कुरु महाजनपद (600 ई.पू.), चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.) (78 ई.), कांची का कैलाशनाथ मंदिर (700-728 ई.), पाल राजवंश (750 ई.)। अतः सबसे अंत में पाल राजवंश।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ब्रह्मस्फुटसिद्धांत   B. चेदि महाजनपद\nC. चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)   D. बंगाल का सेन वंश\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)","ब्रह्मस्फुटसिद्धांत","चेदि महाजनपद","सेन वंश"],"correct":3,"explanation":"चेदि महाजनपद (600 ई.पू.), चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.) (78 ई.), ब्रह्मस्फुटसिद्धांत (628 ई.), बंगाल का सेन वंश (1095 ई.)। अतः सबसे अंत में बंगाल का सेन वंश।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: पल्लव सम्राट महेंद्रवर्मन द्वितीय ने बादामी को जीतकर पुलकेशिन द्वितीय को 510 ई. में सिंहासन से हटा दिया था।\nकथन-2: बनावली से समकोण (90°) पर काटती हुई ग्रिड सड़कों के साथ विशाल पक्की ईंटों का गोदीबाड़ा मिला है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) पल्लव राजा नरसिंहवर्मन प्रथम (मामल्ल) ने 642 ई. में चालुक्य राजधानी वातापी पर विजय पाकर पुलकेशिन द्वितीय का वध किया व 'वातापीकोण्ड' उपाधि ली। (2) बनावली में सड़कें न समकोण पर काटती थीं न जल निकासी व्यवस्था सुदृढ़ थी; गोदीबाड़ा लोथल में था।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन स्मारक एवं निर्माता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भीतरगाँव मंदिर (कानपुर) : कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)\n2. एलिफेंटा त्रिमूर्ति (घारापुरी) : राष्ट्रकूट नरेश कृष्ण प्रथम\n3. कांची का कैलाशनाथ मंदिर : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\n4. एलोरा का कैलाश मंदिर : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए। (अन्य सही युग्म: भीतरगाँव मंदिर (कानपुर)→पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर, एलिफेंटा त्रिमूर्ति (घारापुरी)→कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प), एलोरा का कैलाश मंदिर→राष्ट्रकूट नरेश कृष्ण प्रथम)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्राचीन राजवंश एवं संस्थापक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बादामी के चालुक्य   |   1. श्रीगुप्त (तीसरी शती ई.)\nB. कांची के पल्लव   |   2. पुलकेशिन प्रथम (जयसिंह के वंशज)\nC. गुप्त वंश   |   3. कुजुल कडफिसेस\nD. कुषाण वंश   |   4. सिंहविष्णु (छठी शती ई.)","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1"],"correct":1,"explanation":"सही सुमेलन: बादामी के चालुक्य (पुलकेशिन प्रथम (जयसिंह के वंशज)), कांची के पल्लव (सिंहविष्णु (छठी शती ई.)), गुप्त वंश (श्रीगुप्त (तीसरी शती ई.)), कुषाण वंश (कुजुल कडफिसेस)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन स्मारक एवं निर्माता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. एलोरा का कैलाश मंदिर : राष्ट्रकूट नरेश कृष्ण प्रथम\n2. कांची का कैलाशनाथ मंदिर : कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)\n3. भीतरगाँव मंदिर (कानपुर) : पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर\n4. दशावतार मंदिर (देवगढ़) : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'कांची का कैलाशनाथ मंदिर' का सही संबंध 'पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'' से है (न कि 'कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)' से)। राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्राचीन स्मारक एवं निर्माता के अंतर्गत 'एलोरा का कैलाश मंदिर' का ऐतिहासिक संबंध 'कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)' से था।\nकथन-2: जैन धर्म में तीर्थंकर नेमिनाथ या अरिष्टनेमि का उल्लेख केवल मध्यकालीन पुराणों में है और वेदों में किसी तीर्थंकर का उल्लेख नहीं है।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'एलोरा का कैलाश मंदिर' का सही संबंध 'राष्ट्रकूट नरेश कृष्ण प्रथम' से था — कृष्ण प्रथम ने ऊपर से नीचे की ओर एक ही बेसाल्ट पहाड़ी काटकर कैलाश मंदिर बनवाया। (2) ऋग्वेद में प्रथम तीर्थंकर ऋषभदेव तथा 22वें तीर्थंकर अरिष्टनेमि (नेमिनाथ) का स्पष्ट उल्लेख प्राप्त होता है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: एलोरा का विश्वप्रसिद्ध एकाश्मक कैलाश मंदिर (गुफा 16) गुप्त सम्राट चंद्रगुप्त द्वितीय द्वारा पक्की ईंटों से बनवाया गया था।\nकथन-2: मौर्य प्रशासन में 'समाहर्ता' आय का आकलन और कर संग्रह करने वाला प्रमुख मंत्री था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (एलोरा का कैलाशनाथ मंदिर राष्ट्रकूट शासक कृष्ण प्रथम द्वारा एक ही पहाड़ी को ऊपर से नीचे तराशकर (Rock-cut Monolithic) बनवाया गया।)। कथन-2 सत्य है (मौर्य प्रशासन में 'समाहर्ता' आय का आकलन और कर संग्रह करने वाला प्रमुख मंत्री था।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: राष्ट्रकूट नरेश ध्रुव (धारावर्ष) दक्षिण से उत्तर भारत की राजनीति में हस्तक्षेप कर कन्नौज त्रिकोणीय संघर्ष जीतने वाला पहला दक्कनी शासक था।\nकथन-2: महावीर स्वामी का जन्म ज्ञातृक कुल में हुआ था; उनके प्रथम शिष्य एवं दामाद जामालि थे। पार्श्वनाथ के 4 महाव्रतों में महावीर ने 5वाँ 'ब्रह्मचर्य' जोड़ा।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) राष्ट्रकूट नरेश ध्रुव (धारावर्ष) दक्षिण से उत्तर भारत की राजनीति में हस्तक्षेप कर कन्नौज त्रिकोणीय संघर्ष जीतने वाला पहला दक्कनी शासक था। (2) महावीर स्वामी का जन्म ज्ञातृक कुल में हुआ था; उनके प्रथम शिष्य एवं दामाद जामालि थे। पार्श्वनाथ के 4 महाव्रतों में महावीर ने 5वाँ 'ब्रह्मचर्य' जोड़ा।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ   B. दशावतार मंदिर (देवगढ़)\nC. अशोक के बाद मौर्य वंश का पतन एवं कारण   D. राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["वंश एवं","दशावतार मंदिर (देवगढ़)","सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ","अशोक के बाद मौर्य वंश का पतन एवं कारण"],"correct":0,"explanation":"सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ (600 ई.पू.), अशोक के बाद मौर्य वंश का पतन एवं कारण (185 ई.पू.), दशावतार मंदिर (देवगढ़) (5वीं-6ठी सदी ई.), राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष (752 ई.)। अतः सबसे अंत में राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ईरानी (हखामनी) एवं सिकंदर का भारत आक्रमण   B. कांची के पल्लव\nC. गुप्त वंश   D. कांची का कैलाशनाथ मंदिर\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["कांची का","कांची के पल्लव","गुप्त वंश","ईरानी (हखामनी) एवं सिकंदर का भारत आक्रमण"],"correct":0,"explanation":"ईरानी (हखामनी) एवं सिकंदर का भारत आक्रमण (326 ई.पू.), गुप्त वंश (275 ई.), कांची के पल्लव (575 ई.), कांची का कैलाशनाथ मंदिर (700-728 ई.)। अतः सबसे अंत में कांची का कैलाशनाथ मंदिर।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बंगाल का सेन वंश   B. हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश)\nC. कांची का कैलाशनाथ मंदिर   D. प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.)","कांची का कैलाशनाथ मंदिर","हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश)","सेन वंश"],"correct":3,"explanation":"प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.) (483 ई.पू.), हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश) (606-647 ई.), कांची का कैलाशनाथ मंदिर (700-728 ई.), बंगाल का सेन वंश (1095 ई.)। अतः सबसे अंत में बंगाल का सेन वंश।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया।\nकथन-2: धौलावीरा सिन्धु सभ्यता का अनोखा नगर है जो दो के बजाय तीन भागों—दुर्ग, मध्य नगर और निचला नगर—में विभक्त था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया। (2) धौलावीरा सिन्धु सभ्यता का अनोखा नगर है जो दो के बजाय तीन भागों—दुर्ग, मध्य नगर और निचला नगर—में विभक्त था।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\n2. दाशराज्ञ युद्ध (परुष्णी नदी) : राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया\n3. पानीपत का तृतीय युद्ध (1761 ई.) : अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (नर्मदा नदी तट पर बादामी चालुक्य शासक पुलकेशिन द्वितीय ने कन्नौज सम्राट हर्षवर्धन के दक्षिण अभियान को रोका।) युग्म 2 सही (दाशराज्ञ युद्ध में भरत जन के राजा सुदास ने रावी (परुष्णी) तट पर दस राजाओं के संघ को हराया।) युग्म 3 सही (पानीपत के तृतीय युद्ध में अफगान शासक अहमद शाह अब्दाली ने मराठों को निर्णायक रूप से हराया।)।"},
  {"q":"बंगाल के सेन वंश का प्रथम स्वतंत्र प्रमुख शासक व संस्थापक कौन था?","options":["सामंतसेन / विजयसेन","कुजुल कडफिसेस","बिम्बिसार (राजधानी: राजगृह)","सिमुक (राजधानी: प्रतिष्ठान/पैठण)"],"correct":0,"explanation":"कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया। विजयसेन की उपलब्धियाँ उमापतिधर रचित 'देवपाड़ा प्रशस्ति' में अंकित हैं।"},
  {"q":"ऐतिहासिक संदर्भ में 'दंतिदुर्ग (संस्थापक, हिरण्यगर्भ यज्ञ); कृष्ण I (एलोरा का एकाश्मक कैलाशनाथ मंदिर); अमोघवर्ष ('कविराजमार्ग' कन्नड़ ग्रंथ)' (प्रमुख शासक व कृति) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["कांची के पल्लव: महेंद्रवर्मन I एवं नरसिंहवर्मन I","राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष","वातापी के चालुक्य: पुलकेशिन II एवं ऐहोल प्रशस्ति","विष्णुवर्धन (वेंगी के चालुक्य) एवं वाकाटक राजवंश"],"correct":1,"explanation":"अमोघवर्ष ने 64 वर्षों तक शासन कर कन्नड़ में 'कविराजमार्ग' व संस्कृत में 'प्रश्नोत्तर रत्नमालिका' की रचना की। अरब यात्री सुलेमान ने उन्हें विश्व के 4 महान राजाओं में गिना।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\n2. तराइन का प्रथम युद्ध (1191 ई.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\n3. तालीकोटा का युद्ध (1565 ई.) : शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की\n4. चौसा का युद्ध (1539 ई.) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: नर्मदा नदी तट पर बादामी चालुक्य शासक पुलकेशिन द्वितीय ने कन्नौज सम्राट हर्षवर्धन के दक्षिण अभियान को रोका। (अन्य सही युग्म: तराइन का प्रथम युद्ध (1191 ई.)→पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया, तालीकोटा का युद्ध (1565 ई.)→दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया, चौसा का युद्ध (1539 ई.)→शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की)।"},
  {"q":"ऐतिहासिक संदर्भ में 'कन्नौज राजधानी; कन्नौज धर्मसभा व प्रयाग महामोक्ष परिषद (प्रत्येक 5 वर्ष); 'नागानंद', 'रत्नावली', 'प्रियदर्शिका' नाटक रचयिता' (प्रमुख उपलब्धियाँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","गौड़ नरेश शशांक, कामरूप व पाल-सेन राजवंश","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन"],"correct":3,"explanation":"हर्ष के दरबारी कवि बाणभट्ट ने 'हर्षचरित' में प्रांतीय व सैन्य प्रशासन का सजीव वर्णन किया। हर्ष को 'सकलोत्तरापथनाथ' कहा गया है। [पुष्यभूति वंश)]"},
  {"q":"मुंबई के निकट 'एलिफेंटा गुफाओं' की प्रसिद्ध 'त्रिमूर्ति सदाशिव' प्रतिमा किस राजवंश काल की देन है?","options":["राष्ट्रकूट नरेश कृष्ण प्रथम","कल्चुरी","पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर","उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)"],"correct":1,"explanation":"एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं। 1987 में इसे यूनेस्को विश्व विरासत घोषित किया गया। [राष्ट्रकूट कालीन (शैव गुफा शिल्प)]"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कांची का कैलाशनाथ मंदिर   B. कंबोज महाजनपद\nC. हीनयान और महायान विभाजन   D. राष्ट्रकूट वंश\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["हीनयान और महायान विभाजन","कंबोज महाजनपद","वंश","कांची का कैलाशनाथ मंदिर"],"correct":2,"explanation":"कंबोज महाजनपद (600 ई.पू.), हीनयान और महायान विभाजन (1वीं सदी ई.), कांची का कैलाशनाथ मंदिर (700-728 ई.), राष्ट्रकूट वंश (752 ई.)। अतः सबसे अंत में राष्ट्रकूट वंश।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. पुष्यमित्र शुंग एवं कण्व वंश (पतंजलि व भरहुत)   B. आर्यभट्ट (कुसुमपुर / पाटलिपुत्र)\nC. बादामी के चालुक्य   D. ऐहोल अभिलेख (634 ई.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["(634 ई.)","बादामी के चालुक्य","आर्यभट्ट (कुसुमपुर / पाटलिपुत्र)","पुष्यमित्र शुंग एवं कण्व वंश (पतंजलि व भरहुत)"],"correct":0,"explanation":"पुष्यमित्र शुंग एवं कण्व वंश (पतंजलि व भरहुत) (185 ई.पू.), आर्यभट्ट (कुसुमपुर / पाटलिपुत्र) (499 ई.), बादामी के चालुक्य (543 ई.), ऐहोल अभिलेख (634 ई.) (634 ई.)। अतः सबसे अंत में ऐहोल अभिलेख (634 ई.)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्राचीन राजवंश एवं संस्थापक के अंतर्गत 'बंगाल का सेन वंश' का ऐतिहासिक संबंध 'बिम्बिसार (राजधानी: राजगृह)' से था।\nकथन-2: आर्यभट्ट ने बताया कि ग्रहण राहु-केतु नहीं बल्कि पृथ्वी व चंद्रमा की छाया के कारण होते हैं।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('बंगाल का सेन वंश' का सही संबंध 'सामंतसेन / विजयसेन' से था — कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया।)। कथन-2 सत्य है (आर्यभट्ट ने बताया कि ग्रहण राहु-केतु नहीं बल्कि पृथ्वी व चंद्रमा की छाया के कारण होते हैं।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दक्कन में सातवाहनों के पश्चात वाकाटक सबसे प्रमुख शक्ति थे जिनके साथ चंद्रगुप्त द्वितीय ने वैवाहिक संबंध स्थापित किए और गुप्त-वाकाटक युग ने अजंता कला को पोषित किया।\nकथन-2: कश्मीरी कवि बिल्हण ने कल्याणी के चालुक्य राजा विक्रमादित्य VI के दरबार में यह महाकाव्य लिखा।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) दक्कन में सातवाहनों के पश्चात वाकाटक सबसे प्रमुख शक्ति थे जिनके साथ चंद्रगुप्त द्वितीय ने वैवाहिक संबंध स्थापित किए और गुप्त-वाकाटक युग ने अजंता कला को पोषित किया। (2) कश्मीरी कवि बिल्हण ने कल्याणी के चालुक्य राजा विक्रमादित्य VI के दरबार में यह महाकाव्य लिखा।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: वाकाटक राजवंश के संस्थापक विंध्यशक्ति ने संपूर्ण उत्तर भारत में कनिष्क के बाद सर्वाधिक शुद्ध संस्कृत शिलालेख मध्य एशिया में लगवाए।\nकथन-2: महाजनपद एवं राजधानियाँ के अंतर्गत 'अंग महाजनपद' का ऐतिहासिक संबंध 'पोटली (पोतन)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) विंध्यशक्ति ने विदर्भ/दक्कन क्षेत्र में वाकाटक वंश की स्थापना की और वाकाटक राजाओं ने प्रवरपुर व वत्सगुल्म शाखाओं से मध्य भारत व दक्कन पर शासन किया। (2) 'अंग महाजनपद' का सही संबंध 'चंपा' से था — भागलपुर-मुंगेर क्षेत्र में स्थित अंग महाजनपद की राजधानी चंपा थी।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. राष्ट्रकूट वंश : दंतिदुर्ग (752 ई.)\n2. बादामी के चालुक्य : गोपाल (लगभग 750 ई.)\n3. पाल राजवंश : श्रीगुप्त (तीसरी शती ई.)\n4. गुप्त वंश : बिम्बिसार (राजधानी: राजगृह)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया। (अन्य सही युग्म: बादामी के चालुक्य→पुलकेशिन प्रथम (जयसिंह के वंशज), पाल राजवंश→गोपाल (लगभग 750 ई.), गुप्त वंश→श्रीगुप्त (तीसरी शती ई.))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्राचीन स्मारक एवं निर्माता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. एलोरा का कैलाश मंदिर   |   1. पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\nB. एलिफेंटा त्रिमूर्ति (घारापुरी)   |   2. पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर\nC. भीतरगाँव मंदिर (कानपुर)   |   3. राष्ट्रकूट नरेश कृष्ण प्रथम\nD. कांची का कैलाशनाथ मंदिर   |   4. कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)","options":["A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: एलोरा का कैलाश मंदिर (राष्ट्रकूट नरेश कृष्ण प्रथम), एलिफेंटा त्रिमूर्ति (घारापुरी) (कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)), भीतरगाँव मंदिर (कानपुर) (पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर), कांची का कैलाशनाथ मंदिर (पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह')।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बादामी के चालुक्य   B. भीतरगाँव मंदिर (कानपुर)\nC. गांधार महाजनपद   D. कुमारगुप्त I, स्कंदगुप्त एवं हूण आक्रमण\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["कुमारगुप्त I, स्कंदगुप्त एवं हूण आक्रमण","चालुक्य","गांधार महाजनपद","भीतरगाँव मंदिर (कानपुर)"],"correct":1,"explanation":"गांधार महाजनपद (600 ई.पू.), भीतरगाँव मंदिर (कानपुर) (5वीं सदी ई.), कुमारगुप्त I, स्कंदगुप्त एवं हूण आक्रमण (510 ई.), बादामी के चालुक्य (543 ई.)। अतः सबसे अंत में बादामी के चालुक्य।"},
  {"q":"वातापी के चालुक्य: पुलकेशिन II एवं ऐहोल प्रशस्ति — इसके संबंध में 'प्रमुख ऐतिहासिक विवरण' कौन/क्या था?","options":["पारमिता (पूर्णताएँ जो बोधिसत्व बनाते हैं); थेरीगाथा (बौद्ध भिक्षुणियों द्वारा रचित प्रथम काव्य); आजीवक (मक्खलि गोसाल)","कुषाण शासक हुविष्क व वासुदेव (शैव मतानुयायी, सिक्कों पर शिव-नंदी); चरक संहिता (चिकित्सा व आयुर्वेद सिद्धांत)","जयसिंह-I द्वारा स्थापना; II के दरबारी रविकीर्ति की '' (जिसमें कालिदास व भारवि का उल्लेख)","उदयगिरि पहाड़ी (ओडिशा) पर प्राकृत-ब्राह्मी में; जैन धर्म संरक्षक, नंद राजा व सातकर्णी से संघर्ष का विवरण"],"correct":2,"explanation":"चालुक्यों ने बेसर मंदिर शैली का विकास किया (पट्टदकल के विरूपाक्ष व पापनाथ मंदिर, ऐहोल का लाड़ खाँ व दुर्गा मंदिर)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ऐहोल अभिलेख (634 ई.)   B. अंग महाजनपद\nC. कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख   D. प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अभिलेख (634 ई.)","प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.)","अंग महाजनपद","कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख"],"correct":0,"explanation":"अंग महाजनपद (600 ई.पू.), प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.) (483 ई.पू.), कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख (प्रथम शती ई.पू.), ऐहोल अभिलेख (634 ई.) (634 ई.)। अतः सबसे अंत में ऐहोल अभिलेख (634 ई.)।"},
  {"q":"पल्लव राजवंश (कांची) का वास्तविक संस्थापक किसे माना जाता है?","options":["कुजुल कडफिसेस","बिम्बिसार (राजधानी: राजगृह)","सिमुक (राजधानी: प्रतिष्ठान/पैठण)","सिंहविष्णु (छठी शती ई.)"],"correct":3,"explanation":"सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी। सिंहविष्णु के दरबार में संस्कृत कवि भारवि निवास करते थे।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. वृहत्संहिता   B. बादामी के चालुक्य\nC. हर्यक वंश: बिम्बिसार एवं अजातशत्रु   D. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["हर्यक वंश: बिम्बिसार एवं अजातशत्रु","का युद्ध","वृहत्संहिता","बादामी के चालुक्य"],"correct":1,"explanation":"हर्यक वंश: बिम्बिसार एवं अजातशत्रु (544 ई.पू.), बादामी के चालुक्य (543 ई.), वृहत्संहिता (छठी सदी ई.), नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) (618 ई.)। अतः सबसे अंत में नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)।"},
  {"q":"[UPSC Prelims PYQ] प्राचीन भारत के इतिहास के संदर्भ में, कुषाण-गुप्तोत्तर काल में 'हुंडी' और 'श्रेणी' संस्थाएँ किससे संबंधित थीं?","options":["शाही सेना के अश्वारोही दस्ते","धार्मिक मंदिरों की नृत्य परंपरा","वाणिज्यिक विनिमय पत्र","प्रांतीय गुप्तचर पुलिस अधिकारी"],"correct":2,"explanation":"श्रेणियाँ (Guilds) प्राचीन भारत में बैंकर की तरह जमा स्वीकार करती थीं व ब्याज देती थीं, जबकि हुंडी ऋण/भुगतान का विनिमय पत्र था। [विनिमय बिल]"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बादामी के चालुक्य   B. चंद्रगुप्त मौर्य (सैंड्रोकोटस) एवं सेल्यूकस निकेटर संधि\nC. वत्स महाजनपद   D. सम्राट बिंदुसार (अमित्रघात) एवं आजीवक संबंध\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["चालुक्य","चंद्रगुप्त मौर्य (सैंड्रोकोटस) एवं सेल्यूकस निकेटर संधि","सम्राट बिंदुसार (अमित्रघात) एवं आजीवक संबंध","वत्स महाजनपद"],"correct":0,"explanation":"वत्स महाजनपद (600 ई.पू.), चंद्रगुप्त मौर्य (सैंड्रोकोटस) एवं सेल्यूकस निकेटर संधि (322 ई.पू.), सम्राट बिंदुसार (अमित्रघात) एवं आजीवक संबंध (298 ई.पू.), बादामी के चालुक्य (543 ई.)। अतः सबसे अंत में बादामी के चालुक्य।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन स्मारक एवं निर्माता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. एलोरा का कैलाश मंदिर : राष्ट्रकूट नरेश कृष्ण प्रथम\n2. एलिफेंटा त्रिमूर्ति (घारापुरी) : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\n3. कांची का कैलाशनाथ मंदिर : पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर\n4. भीतरगाँव मंदिर (कानपुर) : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: कृष्ण प्रथम ने ऊपर से नीचे की ओर एक ही बेसाल्ट पहाड़ी काटकर कैलाश मंदिर बनवाया। (अन्य सही युग्म: एलिफेंटा त्रिमूर्ति (घारापुरी)→कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प), कांची का कैलाशनाथ मंदिर→पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह', भीतरगाँव मंदिर (कानपुर)→पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कुषाण सम्राट कनिष्क (78 ई. शक संवत) एवं रेशम मार्ग   B. राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष\nC. हाइडेस्पीज का युद्ध (326 ई.पू.)   D. प्रथम व द्वितीय जैन संगीतियाँ एवं संप्रदाय विभाजन\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["प्रथम व द्वितीय जैन संगीतियाँ एवं संप्रदाय विभाजन","कुषाण सम्राट कनिष्क (78 ई. शक संवत) एवं रेशम मार्ग","हाइडेस्पीज का युद्ध (326 ई.पू.)","वंश एवं"],"correct":3,"explanation":"हाइडेस्पीज का युद्ध (326 ई.पू.) (326 ई.पू.), कुषाण सम्राट कनिष्क (78 ई. शक संवत) एवं रेशम मार्ग (78 ई.), प्रथम व द्वितीय जैन संगीतियाँ एवं संप्रदाय विभाजन (512 ई.), राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष (752 ई.)। अतः सबसे अंत में राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष।"},
  {"q":"ऐतिहासिक संदर्भ में 'शशांक (गौड़/बंगाल — हर्ष का प्रतिद्वंद्वी); कामरूप के भास्करवर्मन (हर्ष के मित्र); पाल (गोपाल व धर्मपाल — बौद्ध संरक्षक); सेन (बल्लालसेन व लक्ष्मणसेन)' (प्रमुख क्षेत्रीय शक्तियाँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मेहरगढ़ (बलूचिस्तान, पाकिस्तान)","गौड़ नरेश  व पाल-सेन राजवंश","भीमबेटका शैलाश्रय (रायसेन, मध्य प्रदेश)","हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश)"],"correct":1,"explanation":"सेन शासक बल्लालसेन ने 'दानसागर' व 'अद्भुतसागर' ग्रंथ लिखे और बंगाल में 'कुलीन प्रथा' को संगठित किया। लक्ष्मणसेन के समय बख्तियार खिलजी ने बंगाल पर आक्रमण किया।"},
  {"q":"कांचीपुरम का प्रसिद्ध 'कैलाशनाथ मंदिर' तथा महाबलीपुरम का 'शोर (तटीय) मंदिर' किस पल्लव ने बनवाया?","options":["राष्ट्रकूट नरेश कृष्ण प्रथम","पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर","नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'","उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)"],"correct":2,"explanation":"राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए। बाद में नंदीवर्मन II ने कांची में बैकुंठ पेरुमल मंदिर बनवाया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन स्मारक एवं निर्माता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भीतरगाँव मंदिर (कानपुर) : पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर\n2. एलोरा का कैलाश मंदिर : राष्ट्रकूट नरेश कृष्ण प्रथम\n3. दशावतार मंदिर (देवगढ़) : उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)\n4. एलिफेंटा त्रिमूर्ति (घारापुरी) : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'एलिफेंटा त्रिमूर्ति (घारापुरी)' का सही संबंध 'कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)' से है (न कि 'पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'' से)। एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: पुलकेशिन प्रथम ने छठी सदी (लगभग 543 ई.) में वातापी को राजधानी बनाकर चालुक्य सत्ता स्थापित की।\nकथन-2: प्राचीन प्रशासनिक अधिकारी के अंतर्गत 'उपरिक' का ऐतिहासिक संबंध 'राजकीय अभिलेख व भूमि दस्तावेजों का मुख्य लेखाधिकारी' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (पुलकेशिन प्रथम ने छठी सदी (लगभग 543 ई.) में वातापी को राजधानी बनाकर चालुक्य सत्ता स्थापित की।)। कथन-2 गलत है — 'उपरिक' का सही संबंध 'प्रांत ('भुक्ति') का प्रमुख राज्यपाल (गुप्तकाल)' से था — गुप्त साम्राज्य में प्रांत को 'भुक्ति' कहते थे और उसके शासक को 'उपरिक' या उपरिक महाराज कहा जाता था।"},
  {"q":"ऐतिहासिक संदर्भ में 'वाकाटक (विंध्यशक्ति व प्रवरसेन I — 4 अश्वमेध यज्ञ); वेंगी के पूर्वी चालुक्य (विष्णुवर्धन); कदम्ब (मयूरशर्मन); गंग (कोलार-तलकाड)' (प्रमुख राजवंश विवरण) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष","विष्णुवर्धन","वातापी के चालुक्य: पुलकेशिन II एवं ऐहोल प्रशस्ति","कांची के पल्लव: महेंद्रवर्मन I एवं नरसिंहवर्मन I"],"correct":1,"explanation":"प्रवरसेन द्वितीय की माता प्रभावती गुप्त के पूना व रिद्धपुर ताम्रपत्रों से गुप्त व वाकाटक वंशावली का अमूल्य ऐतिहासिक ज्ञान मिलता है। [वेंगी के चालुक्य]"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन स्मारक एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. एलिफेंटा त्रिमूर्ति (घारापुरी) : कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)\n2. भीतरगाँव मंदिर (कानपुर) : राष्ट्रकूट नरेश कृष्ण प्रथम\n3. एलोरा का कैलाश मंदिर : पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं।) युग्म 2 गलत (सही: भीतरगाँव मंदिर (कानपुर) — पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर)। युग्म 3 गलत (सही: एलोरा का कैलाश मंदिर — राष्ट्रकूट नरेश कृष्ण प्रथम)।"},
  {"q":"ऐतिहासिक संदर्भ में 'जयसिंह-पुलकेशिन I द्वारा स्थापना; पुलकेशिन II के दरबारी रविकीर्ति की 'ऐहोल प्रशस्ति' (जिसमें कालिदास व भारवि का उल्लेख)' (प्रमुख ऐतिहासिक विवरण) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["विष्णुवर्धन (वेंगी के चालुक्य) एवं वाकाटक राजवंश","कांची के पल्लव: महेंद्रवर्मन I एवं नरसिंहवर्मन I","वातापी के चालुक्य: II एवं","राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष"],"correct":2,"explanation":"चालुक्यों ने बेसर मंदिर शैली का विकास किया (पट्टदकल के विरूपाक्ष व पापनाथ मंदिर, ऐहोल का लाड़ खाँ व दुर्गा मंदिर)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. चंद्रगुप्त प्रथम एवं समुद्रगुप्त (प्रयाग प्रशस्ति)   B. मल्ल महाजनपद\nC. हिन्द-यवन (इंडो-ग्रीक) एवं मिनांडर (मिलिंदपन्हो)   D. वातापी के चालुक्य: पुलकेशिन II एवं ऐहोल प्रशस्ति\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["मल्ल महाजनपद","हिन्द-यवन (इंडो-ग्रीक) एवं मिनांडर (मिलिंदपन्हो)","चंद्रगुप्त प्रथम एवं समुद्रगुप्त (प्रयाग प्रशस्ति)","II एवं प्रशस्ति"],"correct":3,"explanation":"मल्ल महाजनपद (600 ई.पू.), हिन्द-यवन (इंडो-ग्रीक) एवं मिनांडर (मिलिंदपन्हो) (165-130 ई.पू.), चंद्रगुप्त प्रथम एवं समुद्रगुप्त (प्रयाग प्रशस्ति) (335-375 ई.), वातापी के चालुक्य: पुलकेशिन II एवं ऐहोल प्रशस्ति (634 ई.)। अतः सबसे अंत में वातापी के चालुक्य: पुलकेशिन II एवं ऐहोल प्रशस्ति।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्राचीन राजवंश एवं संस्थापक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. कांची के पल्लव   |   1. श्रीगुप्त (तीसरी शती ई.)\nB. हर्यक वंश   |   2. सिमुक (राजधानी: प्रतिष्ठान/पैठण)\nC. सातवाहन वंश   |   3. सिंहविष्णु (छठी शती ई.)\nD. गुप्त वंश   |   4. बिम्बिसार (राजधानी: राजगृह)","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: कांची के पल्लव (सिंहविष्णु (छठी शती ई.)), हर्यक वंश (बिम्बिसार (राजधानी: राजगृह)), सातवाहन वंश (सिमुक (राजधानी: प्रतिष्ठान/पैठण)), गुप्त वंश (श्रीगुप्त (तीसरी शती ई.))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: पाल वंश के संस्थापक गोपाल को अराजकता (मात्स्यन्याय) समाप्त करने के लिए जनता/प्रमुख नागरिकों द्वारा राजा चुना गया था (खालिमपुर अभिलेख)।\nकथन-2: जैन धर्म ने आत्मा (जीव) की अनेकता और कठोर कायाक्लेश पर बल दिया, जबकि बौद्ध धर्म ने आत्मा की सत्ता नकार कर 'मध्यम मार्ग' का उपदेश दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) पाल वंश के संस्थापक गोपाल को अराजकता (मात्स्यन्याय) समाप्त करने के लिए जनता/प्रमुख नागरिकों द्वारा राजा चुना गया था (खालिमपुर अभिलेख)। (2) जैन धर्म ने आत्मा (जीव) की अनेकता और कठोर कायाक्लेश पर बल दिया, जबकि बौद्ध धर्म ने आत्मा की सत्ता नकार कर 'मध्यम मार्ग' का उपदेश दिया।"},
  {"q":"[PSC/CDS युग्म पहचान — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. कांची के पल्लव : कुजुल कडफिसेस\n2. पाल राजवंश : गोपाल (लगभग 750 ई.)\n3. कुषाण वंश : सिमुक (राजधानी: प्रतिष्ठान/पैठण)\n4. सातवाहन वंश : बिम्बिसार (राजधानी: राजगृह)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: गोपाल ने बंगाल में अराजकता समाप्त कर 750 ई. में पाल राजवंश की नींव रखी। (अन्य सही युग्म: कांची के पल्लव→सिंहविष्णु (छठी शती ई.), कुषाण वंश→कुजुल कडफिसेस, सातवाहन वंश→सिमुक (राजधानी: प्रतिष्ठान/पैठण))।"},
  {"q":"बंगाल के पाल राजवंश की स्थापना किसने की थी?","options":["बिम्बिसार (राजधानी: राजगृह)","सिमुक (राजधानी: प्रतिष्ठान/पैठण)","कुजुल कडफिसेस","गोपाल (लगभग 750 ई.)"],"correct":3,"explanation":"गोपाल ने बंगाल में अराजकता समाप्त कर 750 ई. में पाल राजवंश की नींव रखी। गोपाल ने बिहार में ओदंतपुरी बौद्ध महाविहार बनवाया; उसके पुत्र धर्मपाल ने विक्रमशिला बनाया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी।\nकथन-2: एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी। (2) एलिफेंटा द्वीप पर स्थित 7 गुफाएँ मुख्यतः भगवान शिव (त्रिमूर्ति, अर्धनारीश्वर, कल्याणसुंदर) को समर्पित हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)' का ऐतिहासिक संबंध 'राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया' से था।\nकथन-2: बादरायण के ब्रह्मसूत्र पर बाद में शंकराचार्य, रामानुज व माध्व ने भाष्य लिखे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)' का सही संबंध 'चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया' से था — नर्मदा नदी तट पर बादामी चालुक्य शासक पुलकेशिन द्वितीय ने कन्नौज सम्राट हर्षवर्धन के दक्षिण अभियान को रोका।)। कथन-2 सत्य है (बादरायण के ब्रह्मसूत्र पर बाद में शंकराचार्य, रामानुज व माध्व ने भाष्य लिखे।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. तालीकोटा का युद्ध (1565 ई.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\n2. पानीपत का द्वितीय युद्ध (1556 ई.) : अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया\n3. हाइडेस्पीज का युद्ध (326 ई.पू.) : सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\n4. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)' का सही संबंध 'चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया' से है (न कि 'राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया' से)। नर्मदा नदी तट पर बादामी चालुक्य शासक पुलकेशिन द्वितीय ने कन्नौज सम्राट हर्षवर्धन के दक्षिण अभियान को रोका।"},
  {"q":"एलोरा की गुफा संख्या 16 में निर्मित भव्य एकाश्मक 'कैलाशनाथ मंदिर' किसने बनवाया?","options":["राष्ट्रकूट नरेश कृष्ण प्रथम","कल्चुरी/राष्ट्रकूट कालीन (शैव गुफा शिल्प)","उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)","पक्की ईंटों व टेराकोटा से निर्मित प्राचीनतम हिंदू मंदिर"],"correct":0,"explanation":"कृष्ण प्रथम ने ऊपर से नीचे की ओर एक ही बेसाल्ट पहाड़ी काटकर कैलाश मंदिर बनवाया। इसमें रावण द्वारा कैलाश उठाने का जीवंत शिल्प दृश्य विश्वप्रसिद्ध है।"},
  {"q":"ऐतिहासिक संदर्भ में 'महेंद्रवर्मन I ('मत्तविलासप्रहसन' हास्य नाटक, शैलकृत मंडप शैली); नरसिंहवर्मन I (महाबलीपुरम के सप्त रथ मंदिर / एकाश्मक)' (स्थापत्य एवं साहित्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["कांची के पल्लव: I एवं I","विष्णुवर्धन (वेंगी के चालुक्य) एवं वाकाटक राजवंश","वातापी के चालुक्य: पुलकेशिन II एवं ऐहोल प्रशस्ति","राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष"],"correct":0,"explanation":"पल्लव राजदरबार में 'किरातार्जुनीयम्' के लेखक भारवि (सिंहविष्णु के दरबार) तथा 'दशकुमारचरितम्' के रचयिता दण्डी निवास करते थे।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. राष्ट्रकूट वंश : बिम्बिसार (राजधानी: राजगृह)\n2. सातवाहन वंश : सिमुक (राजधानी: प्रतिष्ठान/पैठण)\n3. बंगाल का सेन वंश : सामंतसेन / विजयसेन\n4. गुप्त वंश : श्रीगुप्त (तीसरी शती ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'राष्ट्रकूट वंश' का सही संबंध 'दंतिदुर्ग (752 ई.)' से है (न कि 'बिम्बिसार (राजधानी: राजगृह)' से)। दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. बंगाल का सेन वंश : बिम्बिसार (राजधानी: राजगृह)\n2. बादामी के चालुक्य : पुलकेशिन प्रथम (जयसिंह के वंशज)\n3. राष्ट्रकूट वंश : दंतिदुर्ग (752 ई.)\n4. गुप्त वंश : श्रीगुप्त (तीसरी शती ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'बंगाल का सेन वंश' का सही संबंध 'सामंतसेन / विजयसेन' से है (न कि 'बिम्बिसार (राजधानी: राजगृह)' से)। कर्नाटक मूल के सामंतसेन ने राढ़ में सेन वंश की नींव रखी जिसे विजयसेन ने सुदृढ़ किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: महाबलीपुरम का तटीय (शोर) मंदिर पांड्य राजवंश द्वारा 12वीं सदी में कच्ची ईंटों से निर्मित कराया गया था।\nकथन-2: गणेश्वर-जोधपुरा संस्कृति आंध्र प्रदेश के तट पर विकसित हुई और केवल लोहे के हल बनाने के लिए प्रसिद्ध थी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) महाबलीपुरम का शोर मंदिर पल्लव शासक राजसिंह (नरसिंहवर्मन II) द्वारा ग्रेनाइट से निर्मित दक्षिण भारत के प्राचीनतम संरचनात्मक मंदिरों में से एक है। (2) गणेश्वर (सीकर, राजस्थान) प्राक्-हड़प्पा ताम्रपाषाण स्थल था जो हड़प्पा नगरों को खेतड़ी खानों से ताँबा आपूर्ति का प्रमुख केंद्र था।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. चेदि महाजनपद   B. शक शासक रुद्रदामन I एवं जूनागढ़ (गिरनार) अभिलेख\nC. ऐहोल अभिलेख (634 ई.)   D. चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["शक शासक रुद्रदामन I एवं जूनागढ़ (गिरनार) अभिलेख","चेदि महाजनपद","अभिलेख (634 ई.)","चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)"],"correct":2,"explanation":"चेदि महाजनपद (600 ई.पू.), चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.) (78 ई.), शक शासक रुद्रदामन I एवं जूनागढ़ (गिरनार) अभिलेख (150 ई.), ऐहोल अभिलेख (634 ई.) (634 ई.)। अतः सबसे अंत में ऐहोल अभिलेख (634 ई.)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बंगाल का सेन वंश : दंतिदुर्ग (752 ई.)\n2. राष्ट्रकूट वंश : श्रीगुप्त (तीसरी शती ई.)\n3. गुप्त वंश : सिंहविष्णु (छठी शती ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: बंगाल का सेन वंश — सामंतसेन / विजयसेन)। युग्म 2 गलत (सही: राष्ट्रकूट वंश — दंतिदुर्ग (752 ई.))। युग्म 3 गलत (सही: गुप्त वंश — श्रीगुप्त (तीसरी शती ई.))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: प्राचीन स्मारक एवं निर्माता के अंतर्गत 'कांची का कैलाशनाथ मंदिर' का ऐतिहासिक संबंध 'उत्तर भारत के प्राचीनतम शिखर एवं पंचायतन मंदिरों में एक (गुप्तकाल)' से था।\nकथन-2: मेहरगढ़ लौह युग का प्रमुख बंदरगाह नगर था जहाँ से रोमन सिक्के प्राप्त हुए हैं।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'कांची का कैलाशनाथ मंदिर' का सही संबंध 'पल्लव नरेश नरसिंहवर्मन द्वितीय 'राजसिंह'' से था — राजसिंह ने राजसिंह शैली में बलुआ पत्थर व ग्रेनाइट से दक्षिण के प्रथम संरचनात्मक मंदिर बनवाए। (2) मेहरगढ़ नवपाषाण कालीन (लगभग 7000 ई.पू.) कृषि बस्ती थी, लौह युगीन बंदरगाह नहीं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)   B. प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.)\nC. तेरहवाँ वृहद शिलालेख   D. बादामी के चालुक्य\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)","चालुक्य","प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.)","तेरहवाँ वृहद शिलालेख"],"correct":1,"explanation":"प्रथम बौद्ध संगीति (राजगृह, 483 ई.पू.) (483 ई.पू.), तेरहवाँ वृहद शिलालेख (261 ई.पू.), चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.) (78 ई.), बादामी के चालुक्य (543 ई.)। अतः सबसे अंत में बादामी के चालुक्य।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. द्वितीय बौद्ध संगीति (वैशाली, 383 ई.पू.)   B. कुरु महाजनपद\nC. अशोक के बाद मौर्य वंश का पतन एवं कारण   D. एलोरा का कैलाश मंदिर\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अशोक के बाद मौर्य वंश का पतन एवं कारण","द्वितीय बौद्ध संगीति (वैशाली, 383 ई.पू.)","मंदिर","कुरु महाजनपद"],"correct":2,"explanation":"कुरु महाजनपद (600 ई.पू.), द्वितीय बौद्ध संगीति (वैशाली, 383 ई.पू.) (383 ई.पू.), अशोक के बाद मौर्य वंश का पतन एवं कारण (185 ई.पू.), एलोरा का कैलाश मंदिर (8वीं सदी ई.)। अतः सबसे अंत में एलोरा का कैलाश मंदिर।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. द्वितीय बौद्ध संगीति (वैशाली, 383 ई.पू.)   B. अश्मक महाजनपद\nC. बादामी के चालुक्य   D. तृतीय बौद्ध संगीति (पाटलिपुत्र, लगभग 250 ई.पू.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["द्वितीय बौद्ध संगीति (वैशाली, 383 ई.पू.)","चालुक्य","तृतीय बौद्ध संगीति (पाटलिपुत्र, लगभग 250 ई.पू.)","अश्मक महाजनपद"],"correct":1,"explanation":"अश्मक महाजनपद (600 ई.पू.), द्वितीय बौद्ध संगीति (वैशाली, 383 ई.पू.) (383 ई.पू.), तृतीय बौद्ध संगीति (पाटलिपुत्र, लगभग 250 ई.पू.) (250 ई.पू.), बादामी के चालुक्य (543 ई.)। अतः सबसे अंत में बादामी के चालुक्य।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. प्राचीन भारतीय गणित, खगोल व चिकित्सा वैज्ञानिक   B. एलोरा का कैलाश मंदिर\nC. कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख   D. राष्ट्रकूट वंश\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख","प्राचीन भारतीय गणित, खगोल व चिकित्सा वैज्ञानिक","मंदिर","राष्ट्रकूट वंश"],"correct":2,"explanation":"कलिंग राजा खारवेल का हाथीगुम्फा अभिलेख (प्रथम शती ई.पू.), प्राचीन भारतीय गणित, खगोल व चिकित्सा वैज्ञानिक (499 ई.), राष्ट्रकूट वंश (752 ई.), एलोरा का कैलाश मंदिर (8वीं सदी ई.)। अतः सबसे अंत में एलोरा का कैलाश मंदिर।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ऐहोल अभिलेख (634 ई.)   B. राष्ट्रकूट वंश\nC. आर्यभट्ट (कुसुमपुर / पाटलिपुत्र)   D. चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["वंश","ऐहोल अभिलेख (634 ई.)","चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.)","आर्यभट्ट (कुसुमपुर / पाटलिपुत्र)"],"correct":0,"explanation":"चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर, प्रथम शताब्दी ई.) (78 ई.), आर्यभट्ट (कुसुमपुर / पाटलिपुत्र) (499 ई.), ऐहोल अभिलेख (634 ई.) (634 ई.), राष्ट्रकूट वंश (752 ई.)। अतः सबसे अंत में राष्ट्रकूट वंश।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पाल राजवंश : दंतिदुर्ग (752 ई.)\n2. राष्ट्रकूट वंश : बिम्बिसार (राजधानी: राजगृह)\n3. हर्यक वंश : सिमुक (राजधानी: प्रतिष्ठान/पैठण)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: पाल राजवंश — गोपाल (लगभग 750 ई.))। युग्म 2 गलत (सही: राष्ट्रकूट वंश — दंतिदुर्ग (752 ई.))। युग्म 3 गलत (सही: हर्यक वंश — बिम्बिसार (राजधानी: राजगृह))।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश)   B. सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ\nC. बादामी के चालुक्य   D. राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["बादामी के चालुक्य","वंश एवं","हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश)","सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ"],"correct":1,"explanation":"सोलह महाजनपदों का उल्लेख एवं प्रमुख राजधानियाँ (600 ई.पू.), बादामी के चालुक्य (543 ई.), हर्षवर्धन, ह्वेनसांग एवं बाणभट्ट (वर्धन/पुष्यभूति वंश) (606-647 ई.), राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष (752 ई.)। अतः सबसे अंत में राष्ट्रकूट वंश एवं कन्नौज हेतु त्रिकोणीय संघर्ष।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. बादामी के चालुक्य : सामंतसेन / विजयसेन\n2. पाल राजवंश : गोपाल (लगभग 750 ई.)\n3. कांची के पल्लव : सिंहविष्णु (छठी शती ई.)\n4. हर्यक वंश : बिम्बिसार (राजधानी: राजगृह)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'बादामी के चालुक्य' का सही संबंध 'पुलकेशिन प्रथम (जयसिंह के वंशज)' से है (न कि 'सामंतसेन / विजयसेन' से)। पुलकेशिन प्रथम ने छठी सदी (लगभग 543 ई.) में वातापी को राजधानी बनाकर चालुक्य सत्ता स्थापित की।"}
]);
